  function formatCell(v) {
    if (v == null) return "None";
    if (typeof v === "boolean") return String(v);
    if (typeof v === "number") {
      if (!isFinite(v)) return v > 0 ? "Inf" : "-Inf";
      // Match Python's %.12g
      var s = v.toPrecision(12);
      return String(parseFloat(s));
