  // ── Filtering ──────────────────────────────────────────────

  function applyFilter(state) {
    if (state.filterTokens.length === 0) {
      state.filteredRows = state.allRows.slice();
    } else {
      state.filteredRows = state.allRows.filter(function (row) {
        for (var i = 0; i < state.filterTokens.length; i++) {
