        if (v == null) return false;
        var sv = String(v), fv = tok.value;
        if (!tok.caseSensitive) { sv = sv.toLowerCase(); fv = fv.toLowerCase(); }
        return sv.indexOf(fv) === -1;
      }
      case "starts_with": {
        if (v == null) return false;
        var sv = String(v), fv = tok.value;
        if (!tok.caseSensitive) { sv = sv.toLowerCase(); fv = fv.toLowerCase(); }
